import React, { useState, useRef, useEffect } from "react";
import axios from "axios";
import QRCode from "react-qr-code";
import { Link } from "react-router-dom";
import html2canvas from "html2canvas";
import * as faceapi from "face-api.js";

function Register() {
  const [formData, setFormData] = useState({
    name: "",
    college_name: "",
    phone: "",
    event_id: ""
  });

  const [qrData, setQrData] = useState("");
  const [userId, setUserId] = useState("");
  const [photo, setPhoto] = useState(null);
  const [faceDetected, setFaceDetected] = useState(false);
  const [warning, setWarning] = useState("");
  const [modelsLoaded, setModelsLoaded] = useState(false);

  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const idCardRef = useRef(null);
  const streamRef = useRef(null);

  // ✅ Load Face Detection Model
  useEffect(() => {
    const loadModels = async () => {
      try {
        await faceapi.nets.tinyFaceDetector.loadFromUri("/models");
        setModelsLoaded(true);
        console.log("Face model loaded successfully");
      } catch (err) {
        console.error("Model loading error:", err);
      }
    };

    loadModels();
  }, []);

  // ✅ Handle Form Input
  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  // ✅ Open Camera
  const openCamera = async () => {
  if (!modelsLoaded) {
    alert("Face model not loaded yet.");
    return;
  }

  try {
    const stream = await navigator.mediaDevices.getUserMedia({ video: true });
    videoRef.current.srcObject = stream;
    streamRef.current = stream;

    videoRef.current.onloadedmetadata = () => {
      videoRef.current.play();
      detectFace();
    };

  } catch (err) {
    console.error("Camera error:", err);
    alert("Unable to access camera.");
  }
};

const detectFace = async () => {
  if (!videoRef.current) return;

  const detection = await faceapi.detectSingleFace(
    videoRef.current,
    new faceapi.TinyFaceDetectorOptions()
  );

  if (detection) {
    setFaceDetected(true);
    setWarning("");
  } else {
    setFaceDetected(false);
    setWarning("⚠ Face not detected! Please position properly.");
  }

  requestAnimationFrame(detectFace);
};

  // ✅ Capture Photo
 const capturePhoto = () => {
  if (!videoRef.current) return;

  const context = canvasRef.current.getContext("2d");

  canvasRef.current.width = videoRef.current.videoWidth;
  canvasRef.current.height = videoRef.current.videoHeight;

  context.drawImage(
    videoRef.current,
    0,
    0,
    canvasRef.current.width,
    canvasRef.current.height
  );

  const imageData = canvasRef.current.toDataURL("image/png");
  setPhoto(imageData);

  // Stop camera after capture
  if (streamRef.current) {
    streamRef.current.getTracks().forEach((track) => track.stop());
  }
};

  // ✅ Submit Form
  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const res = await axios.post("http://localhost:5000/register", formData);

      setQrData(res.data.qrData);
      setUserId(res.data.userId);

      alert("Registration Successful! Now take photo.");
    } catch (error) {
      console.error("Registration error:", error);
      alert("Registration failed. Check backend.");
    }
  };

  // ✅ Download ID Card
  const downloadCard = () => {
    html2canvas(idCardRef.current).then((canvas) => {
      const link = document.createElement("a");
      link.download = "IDCard.png";
      link.href = canvas.toDataURL();
      link.click();
    });
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Event Registration</h2>

      <form onSubmit={handleSubmit}>
        <input name="name" placeholder="Name" onChange={handleChange} required />
        <br /><br />

        <input name="college_name" placeholder="College Name" onChange={handleChange} required />
        <br /><br />

        <input name="phone" placeholder="Phone" onChange={handleChange} required />
        <br /><br />

        <select name="event_id" onChange={handleChange} required>
          <option value="">Select Event</option>
          <option value="1">Technical Event</option>
          <option value="2">Cultural Event</option>
        </select>
        <br /><br />

        <button type="submit">Register</button>
      </form>

      {qrData && (
        <>
          <h3>Take Photo</h3>
          <button onClick={openCamera}>Open Camera</button>
          <br /><br />

          <video ref={videoRef} autoPlay width="200"></video><br />

{faceDetected ? (
  <p style={{ color: "green" }}>Face Detected ✅</p>
) : (
  <p style={{ color: "red" }}>No Face Detected ❌</p>
)}

{warning && <p style={{ color: "red" }}>{warning}</p>}

          <button onClick={capturePhoto} disabled={!faceDetected}>
                  Capture Photo
          </button>
            

          <canvas
            ref={canvasRef}
            width="200"
            height="150"
            style={{ display: "none" }}
          ></canvas>
        </>
      )}

      {photo && (
        <>
          <div
            ref={idCardRef}
            style={{
              border: "2px solid black",
              width: "300px",
              padding: "10px",
              marginTop: "20px"
            }}
          >
            <h3>College Event ID Card</h3>
            <p><strong>Name:</strong> {formData.name}</p>
            <p><strong>Event No:</strong> {formData.event_id}</p>
            <p><strong>User ID:</strong> {userId}</p>

            <QRCode value={qrData} size={100} />
            <br /><br />

            <img src={photo} alt="User" width="100" />
          </div>

          <button onClick={downloadCard}>Download ID Card</button>
        </>
        
      )}
    </div>
  );
}

export default Register;
